import yfinance as yf; T=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; print("===== INTRADAY MONITOR ====="); exec('for t in T:\n try:\n  d=yf.download(t,period="1d",interval="5m",progress=False,auto_adjust=True,prepost=False)\n  if d.empty: print("\\n"+t+" : aucune donnee intraday"); continue\n  print("\\n"+t)\n  for idx,row in d.head(4).iterrows(): print("{} | O={:.2f} H={:.2f} L={:.2f} C={:.2f} V={}".format(idx,float(row["Open"].squeeze()),float(row["High"].squeeze()),float(row["Low"].squeeze()),float(row["Close"].squeeze()),int(row["Volume"].squeeze())))\n except Exception as e: print(t+" : erreur "+str(e))')
